-- Base tables, generated from lib/db/src/schema/finverify.ts with `drizzle-kit export`.
-- Every statement is idempotent, so running this against a database that already has the tables changes nothing.
-- Do not edit this file: a later change to the schema is a new numbered file in this folder.

CREATE TABLE IF NOT EXISTS "ai_extractions" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"upload_id" integer,
	"entity_type" text NOT NULL,
	"entity_id" integer,
	"provider" text NOT NULL,
	"model" text,
	"purpose" text NOT NULL,
	"extracted_json" jsonb NOT NULL,
	"confidence" numeric(5, 4) DEFAULT '0' NOT NULL,
	"status" text DEFAULT 'extracted_pending_review' NOT NULL,
	"created_by" integer,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "ai_provider_settings" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"gemini_model" text,
	"gemini_fallback_model" text,
	"nvidia_model" text,
	"openrouter_model" text,
	"openrouter_enabled" boolean DEFAULT false NOT NULL,
	"provider_order" jsonb,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "ai_usage_logs" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"user_id" integer,
	"provider" text NOT NULL,
	"model" text,
	"purpose" text NOT NULL,
	"success" boolean DEFAULT false NOT NULL,
	"latency_ms" integer DEFAULT 0 NOT NULL,
	"token_estimate" integer,
	"used_fallback" boolean DEFAULT false NOT NULL,
	"error_code" text,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "audit_logs" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"user_id" integer,
	"actor_email" text,
	"action" text NOT NULL,
	"entity_type" text NOT NULL,
	"entity_id" integer,
	"metadata" jsonb,
	"ip_address" text,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "auth_sessions" (
	"id" serial PRIMARY KEY NOT NULL,
	"user_id" integer NOT NULL,
	"company_id" integer NOT NULL,
	"token_hash" text NOT NULL,
	"user_agent" text,
	"ip_address" text,
	"expires_at" timestamp NOT NULL,
	"revoked_at" timestamp,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "bank_transactions" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"date" text NOT NULL,
	"narration" text NOT NULL,
	"amount" numeric(14, 2) NOT NULL,
	"type" text NOT NULL,
	"source" text DEFAULT 'bank' NOT NULL,
	"bank_name" text,
	"reference" text,
	"status" text DEFAULT 'unverified' NOT NULL,
	"confidence_score" integer DEFAULT 0 NOT NULL,
	"matched_invoice_id" integer,
	"note" text,
	"source_upload_id" integer,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "ca_client_links" (
	"id" serial PRIMARY KEY NOT NULL,
	"ca_user_id" integer NOT NULL,
	"ca_company_id" integer,
	"client_company_id" integer NOT NULL,
	"client_name" text,
	"status" text DEFAULT 'active' NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "ca_review_items" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"monthly_close_period_id" integer,
	"exception_id" integer,
	"entity_type" text NOT NULL,
	"entity_id" integer,
	"title" text NOT NULL,
	"description" text,
	"severity" text DEFAULT 'medium' NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"assigned_to" integer,
	"founder_note" text,
	"ca_note" text,
	"requested_documents_json" jsonb,
	"evidence_json" jsonb,
	"created_by" integer,
	"resolved_by" integer,
	"resolved_at" timestamp,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "companies" (
	"id" serial PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"industry" text NOT NULL,
	"monthly_revenue_range" text,
	"ca_email" text,
	"gstin" text,
	"pan" text,
	"financial_year_start" text DEFAULT 'April' NOT NULL,
	"currency" text DEFAULT 'INR' NOT NULL,
	"data_retention_days" integer DEFAULT 365 NOT NULL,
	"plan" text DEFAULT 'free' NOT NULL,
	"plan_until" timestamp,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "document_requests" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer NOT NULL,
	"monthly_close_period_id" integer,
	"requested_by" integer,
	"assigned_to" integer,
	"related_entity_type" text,
	"related_entity_id" integer,
	"title" text NOT NULL,
	"description" text,
	"required_document_type" text DEFAULT 'other' NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"priority" text DEFAULT 'medium' NOT NULL,
	"due_date" timestamp,
	"uploaded_file_id" integer,
	"ca_comment" text,
	"founder_comment" text,
	"resolved_by" integer,
	"resolved_at" timestamp,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "documents" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"upload_batch_id" integer,
	"file_name" text NOT NULL,
	"source_type" text NOT NULL,
	"mime_type" text,
	"storage_provider" text DEFAULT 'metadata_only' NOT NULL,
	"storage_key" text,
	"storage_bucket" text,
	"storage_region" text,
	"storage_url" text,
	"size_bytes" integer,
	"checksum_sha256" text,
	"status" text DEFAULT 'metadata_captured' NOT NULL,
	"extracted_text_status" text DEFAULT 'not_started' NOT NULL,
	"row_count" integer,
	"detected_columns" jsonb,
	"uploaded_by_user_id" integer,
	"retention_until" timestamp,
	"deleted_at" timestamp,
	"deleted_by_user_id" integer,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "evidence_items" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer NOT NULL,
	"entity_type" text NOT NULL,
	"entity_id" integer NOT NULL,
	"upload_id" integer,
	"source_type" text,
	"source_file_name" text,
	"source_page" integer,
	"source_row_number" integer,
	"source_text_snippet" text,
	"source_json" jsonb,
	"confidence" numeric(5, 4),
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "exceptions" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer NOT NULL,
	"monthly_close_period_id" integer,
	"type" text NOT NULL,
	"title" text NOT NULL,
	"description" text,
	"severity" text DEFAULT 'medium' NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"related_entity_type" text,
	"related_entity_id" integer,
	"assigned_to" integer,
	"created_by" integer,
	"resolved_by" integer,
	"resolved_at" timestamp,
	"resolution_note" text,
	"evidence_json" jsonb,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "file_access_logs" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"user_id" integer,
	"file_upload_id" integer,
	"r2_key" text,
	"action" text NOT NULL,
	"ip_address" text,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "file_uploads" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"user_id" integer,
	"source_type" text NOT NULL,
	"original_file_name" text NOT NULL,
	"mime_type" text,
	"size_bytes" integer DEFAULT 0 NOT NULL,
	"r2_key" text,
	"encrypted" boolean DEFAULT true NOT NULL,
	"encryption_version" text DEFAULT 'r2-managed' NOT NULL,
	"status" text DEFAULT 'stored' NOT NULL,
	"parsed_row_count" integer,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "gateway_settlements" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"provider" text NOT NULL,
	"settlement_id" text NOT NULL,
	"gross_amount" numeric(14, 2) NOT NULL,
	"fees" numeric(14, 2) DEFAULT '0' NOT NULL,
	"gst_on_fees" numeric(14, 2),
	"net_amount" numeric(14, 2) NOT NULL,
	"settlement_date" text NOT NULL,
	"bank_reference" text,
	"status" text DEFAULT 'matched' NOT NULL,
	"bank_transaction_id" integer,
	"source_upload_id" integer,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "gst_records" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"period" text NOT NULL,
	"source_type" text NOT NULL,
	"gstin" text,
	"counterparty_name" text,
	"invoice_number" text,
	"invoice_date" text,
	"taxable_value" numeric(14, 2) DEFAULT '0' NOT NULL,
	"gst_amount" numeric(14, 2) DEFAULT '0' NOT NULL,
	"match_status" text DEFAULT 'unmatched' NOT NULL,
	"risk_status" text DEFAULT 'none' NOT NULL,
	"source_upload_id" integer,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "invoices" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"invoice_number" text NOT NULL,
	"vendor_name" text NOT NULL,
	"customer_name" text,
	"gstin" text,
	"date" text NOT NULL,
	"amount" numeric(14, 2) NOT NULL,
	"gst_amount" numeric(14, 2),
	"type" text DEFAULT 'purchase' NOT NULL,
	"payment_status" text DEFAULT 'unpaid' NOT NULL,
	"status" text DEFAULT 'unverified' NOT NULL,
	"linked_transaction_id" integer,
	"source_upload_id" integer,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "ledger_entries" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"date" text NOT NULL,
	"ledger_name" text NOT NULL,
	"voucher_number" text,
	"amount" numeric(14, 2) NOT NULL,
	"debit_credit" text NOT NULL,
	"source_tool" text DEFAULT 'manual' NOT NULL,
	"status" text DEFAULT 'unmatched' NOT NULL,
	"matched_transaction_id" integer,
	"source_upload_id" integer,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "monthly_close_periods" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer NOT NULL,
	"month" integer NOT NULL,
	"year" integer NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"verification_score" integer DEFAULT 0 NOT NULL,
	"verified_amount" numeric(14, 2) DEFAULT '0' NOT NULL,
	"unverified_amount" numeric(14, 2) DEFAULT '0' NOT NULL,
	"missing_documents_count" integer DEFAULT 0 NOT NULL,
	"risk_flags_count" integer DEFAULT 0 NOT NULL,
	"ca_review_items_count" integer DEFAULT 0 NOT NULL,
	"uploaded_sources_json" jsonb,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "oauth_accounts" (
	"id" serial PRIMARY KEY NOT NULL,
	"user_id" integer NOT NULL,
	"company_id" integer NOT NULL,
	"provider" text NOT NULL,
	"provider_user_id" text NOT NULL,
	"email" text NOT NULL,
	"name" text,
	"avatar_url" text,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"last_login_at" timestamp
);

CREATE TABLE IF NOT EXISTS "payroll_entries" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"employee_name" text NOT NULL,
	"month" text NOT NULL,
	"gross_amount" numeric(14, 2),
	"net_amount" numeric(14, 2) NOT NULL,
	"payment_date" text,
	"bank_reference" text,
	"status" text DEFAULT 'verified' NOT NULL,
	"source_upload_id" integer,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "reconciliation_matches" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"bank_transaction_id" integer,
	"invoice_id" integer,
	"ledger_entry_id" integer,
	"run_id" text,
	"match_type" text NOT NULL,
	"confidence_score" integer DEFAULT 0 NOT NULL,
	"reason" text NOT NULL,
	"reason_json" jsonb,
	"evidence_json" jsonb,
	"status" text DEFAULT 'pending' NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "risk_flags" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"entity_type" text NOT NULL,
	"entity_id" integer,
	"category" text NOT NULL,
	"severity" text NOT NULL,
	"reason" text NOT NULL,
	"suggested_action" text NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "role_permissions" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"role" text NOT NULL,
	"permission" text NOT NULL,
	"enabled" boolean DEFAULT true NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "tally_bills" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"party" text NOT NULL,
	"group" text NOT NULL,
	"ref" text NOT NULL,
	"date" text NOT NULL,
	"amount" numeric(16, 2) DEFAULT '0' NOT NULL,
	"type" text DEFAULT 'New Ref' NOT NULL
);

CREATE TABLE IF NOT EXISTS "tally_fixed_assets" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"name" text NOT NULL,
	"block" text NOT NULL,
	"rate" numeric(6, 2) DEFAULT '0' NOT NULL,
	"opening_wdv" numeric(16, 2) DEFAULT '0' NOT NULL,
	"additions" numeric(16, 2) DEFAULT '0' NOT NULL,
	"addition_date" text,
	"deletions" numeric(16, 2) DEFAULT '0' NOT NULL,
	"deletion_date" text,
	"depreciation" numeric(16, 2) DEFAULT '0' NOT NULL,
	"closing_wdv" numeric(16, 2) DEFAULT '0' NOT NULL
);

CREATE TABLE IF NOT EXISTS "tally_ledgers" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"name" text NOT NULL,
	"group" text NOT NULL,
	"opening_balance" numeric(16, 2) DEFAULT '0' NOT NULL,
	"closing_balance" numeric(16, 2) DEFAULT '0' NOT NULL,
	"prev_year_closing" numeric(16, 2),
	"prev_year_group" text,
	"is_msme" boolean DEFAULT false NOT NULL,
	"msme_type" text,
	"pan" text,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "tally_voucher_lines" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"voucher_number" text NOT NULL,
	"ledger" text NOT NULL,
	"group" text NOT NULL,
	"debit" numeric(16, 2) DEFAULT '0' NOT NULL,
	"credit" numeric(16, 2) DEFAULT '0' NOT NULL
);

CREATE TABLE IF NOT EXISTS "tally_vouchers" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"date" text NOT NULL,
	"type" text NOT NULL,
	"number" text NOT NULL,
	"party" text,
	"narration" text,
	"amount" numeric(16, 2) DEFAULT '0' NOT NULL,
	"mode" text,
	"created_at" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS "upload_batches" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"source_type" text NOT NULL,
	"file_name" text NOT NULL,
	"status" text DEFAULT 'processed' NOT NULL,
	"uploaded_at" timestamp DEFAULT now() NOT NULL,
	"record_count" integer,
	"run_id" text
);

CREATE TABLE IF NOT EXISTS "users" (
	"id" serial PRIMARY KEY NOT NULL,
	"company_id" integer,
	"name" text NOT NULL,
	"email" text NOT NULL,
	"password_hash" text,
	"password_salt" text,
	"neon_user_id" text,
	"role" text DEFAULT 'founder' NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"last_login_at" timestamp,
	"created_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "users_neon_user_id_unique" UNIQUE("neon_user_id")
);
